package android.view; public class ViewGroup extends View {public java.util.ArrayList<View> children=new java.util.ArrayList<>();public ViewGroup(android.content.Context c){super(c);}public static class LayoutParams{public int width,height;public LayoutParams(int w,int h){width=w;height=h;}}public int getChildCount(){return children.size();}public View getChildAt(int i){return i>=0&&i<children.size()?children.get(i):null;}public void removeView(View v){children.remove(v);v.parent=null;}public void addView(View v){if(v.parent!=null)throw new IllegalStateException();children.add(v);v.parent=this;}public void addView(View v,LayoutParams p){v.params=p;addView(v);}}